
<?php
require_once __DIR__ . '/../config/database.php';
function h($value): string { return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8'); }
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$id || $id < 1) { header('Location: stafi.php'); exit; }
$stmt = $pdo->prepare('SELECT staf_id, emri, mbiemri, telefoni, email, pozita, data_punesimit, foto, statusi FROM stafi WHERE staf_id = ?');
$stmt->execute([$id]);
$person = $stmt->fetch(PDO::FETCH_ASSOC);
if (!$person) { http_response_code(404); exit('Punonjësja nuk u gjet. <a href="stafi.php">Kthehu te stafi</a>'); }
$initials = mb_strtoupper(mb_substr($person['emri'],0,1).mb_substr($person['mbiemri'],0,1));
$stmt = $pdo->prepare("SELECT t.termin_id, t.data, t.ora, t.statusi, k.emri AS klient_emri, k.mbiemri AS klient_mbiemri, s.emri AS sherbimi, s.cmimi FROM terminet t LEFT JOIN klientet k ON k.klient_id=t.klient_id LEFT JOIN sherbimet s ON s.sherbim_id=t.sherbim_id WHERE t.staf_id=? ORDER BY t.data DESC, t.ora DESC");
$stmt->execute([$id]);
$appointments = $stmt->fetchAll(PDO::FETCH_ASSOC);
$total = count($appointments); $completed = 0; $today = 0;
foreach ($appointments as $a) { if (mb_strtolower(trim((string)$a['statusi'])) === 'përfunduar') $completed++; if (($a['data'] ?? '') === date('Y-m-d')) $today++; }
?>
