<section class="card"><div class="section-head"><div><h2>Terminet e punonjëses</h2><div class="muted">Lista e termineve të lidhura me këtë anëtare të ekipit.</div></div><span class="count"><?= $total ?> termine</span></div>
<?php if (!$appointments): ?><div class="empty">Nuk ka ende termine të caktuara për këtë punonjëse.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ora</th><th>Klientja</th><th>Shërbimi</th><th>Çmimi</th><th>Statusi</th></tr></thead><tbody><?php foreach($appointments as $a): ?><tr><td><?= h(date('d.m.Y',strtotime($a['data']))) ?></td><td><?= h(substr((string)$a['ora'],0,5)) ?></td><td><?= h(trim(($a['klient_emri'] ?? '').' '.($a['klient_mbiemri'] ?? '')) ?: '—') ?></td><td><?= h($a['sherbimi'] ?? '—') ?></td><td><?= $a['cmimi'] !== null ? h(number_format((float)$a['cmimi'],2,',','.').' €') : '—' ?></td><td><span class="badge"><?= h($a['statusi'] ?: 'Ne pritje') ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
